-- A DataGateway row can belong to a plugin (#1083): `plugin_id` names the
-- plugin, and the three connection fields become nullable, because a plugin
-- DataGateway runs in the coordinator and has no address of its own.
--
-- Generated by `prisma migrate diff`, with the CHECK constraint added by hand:
-- Prisma has no way to declare one.

-- AlterTable
ALTER TABLE "data_gateways" ADD COLUMN     "plugin_id" TEXT,
ALTER COLUMN "auth_type" DROP NOT NULL,
ALTER COLUMN "connection_port" DROP NOT NULL,
ALTER COLUMN "connection_url" DROP NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "data_gateways_plugin_id_key" ON "data_gateways"("plugin_id");

-- AddForeignKey
ALTER TABLE "data_gateways" ADD CONSTRAINT "data_gateways_plugin_id_fkey" FOREIGN KEY ("plugin_id") REFERENCES "plugins"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- A row is one kind or the other: a remote DataGateway has all three
-- connection fields and no plugin, and a plugin DataGateway has its plugin
-- and none of the three. Every row from before this migration is a remote
-- DataGateway with all three set, so the constraint can't fail here.
ALTER TABLE "data_gateways" ADD CONSTRAINT "data_gateways_row_kind" CHECK (
  ("plugin_id" IS NULL AND "connection_url" IS NOT NULL AND "connection_port" IS NOT NULL AND "auth_type" IS NOT NULL)
  OR
  ("plugin_id" IS NOT NULL AND "connection_url" IS NULL AND "connection_port" IS NULL AND "auth_type" IS NULL)
);
